import{_ as s,C as r,c as a,o as n,a3 as e,G as d}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Routes overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/routes/index.md","filePath":"master/supply-chain/inventories/routes/index.md","lastUpdated":1792041590000}'),i={name:"master/supply-chain/inventories/routes/index.md"};function h(l,t,u,p,c,g){const o=r("ImagePopup");return n(),a("div",null,[t[0]||(t[0]=e('<h1 id="routes-overview" tabindex="-1">Routes overview <a class="header-anchor" href="#routes-overview" aria-label="Permalink to &quot;Routes overview&quot;">​</a></h1><p>A route is the path goods follow through your warehouse. It answers questions such as: do received goods go straight to stock, or through quality control first? Do deliveries go from stock to the customer, or through picking and packing?</p><blockquote><p><strong>In simple words:</strong> A route is a saved chain of steps. Each step is a rule that says where goods come from and where they go next.</p></blockquote><p>Routes and rules live in <code>Inventory → Configurations → Warehouse Management</code>.</p><h2 id="key-words" tabindex="-1">Key words <a class="header-anchor" href="#key-words" aria-label="Permalink to &quot;Key words&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Route</strong></td><td>A named set of rules, for example &quot;Receive in 3 steps&quot;</td></tr><tr><td><strong>Rule</strong></td><td>One step: from a source location to a destination, using an operation type</td></tr><tr><td><strong>Pull</strong></td><td>A step is created because a later step needs goods. Delivery works this way</td></tr><tr><td><strong>Push</strong></td><td>A step is created because goods just arrived. Receiving works this way</td></tr><tr><td><strong>Operation type</strong></td><td>The kind of document the step creates, such as Receipts or Pick</td></tr></tbody></table><p>Pull works backwards from demand. A customer order asks <code>Partners/Customers</code> for goods, so a pick pulls them from stock. Push works forwards from arrival. Goods land in <code>WH/Input</code>, so a rule pushes them on to quality control.</p><h2 id="standard-routes" tabindex="-1">Standard routes <a class="header-anchor" href="#standard-routes" aria-label="Permalink to &quot;Standard routes&quot;">​</a></h2><p>Each warehouse creates its routes from the step choices in the warehouse form. In the example warehouse <strong>WH</strong> these routes exist:</p><ul><li><strong>Receive in 3 steps (Input + Quality + Stock)</strong></li><li><strong>Deliver in 3 steps (Pick + Pack + Ship)</strong></li><li><strong>Pick components, manufacture and then store products (3 steps)</strong></li><li><strong>Cross-Dock</strong></li></ul><p>The <strong>Routes</strong> list shows these 4 active routes, and its <strong>Archived</strong> tab holds 3 more. The warehouse <strong>Routes</strong> page, titled <strong>Manage My Company Routes</strong>, lists only the first three. <strong>Cross-Dock</strong> is not on that page.</p><p>You normally never build these by hand. Choose the step counts in the warehouse and Aureus keeps the routes in line. See <a href="./../warehouses/warehouses.html">Warehouses</a>.</p><h2 id="when-you-need-multi-steps-routes" tabindex="-1">When you need Multi Steps Routes <a class="header-anchor" href="#when-you-need-multi-steps-routes" aria-label="Permalink to &quot;When you need Multi Steps Routes&quot;">​</a></h2><p>The one-step flow works with no extra setting. To choose two or three steps, switch on <code>Inventory → Settings → Manage Warehouses → Multi Steps Routes</code>. The <strong>Incoming Shipments</strong> and <strong>Outgoing Shipments</strong> options then appear on the warehouse form. The Routes, Rules, Storage Categories and Putaway Rules menus also appear.</p><h2 id="flows-at-a-glance" tabindex="-1">Flows at a glance <a class="header-anchor" href="#flows-at-a-glance" aria-label="Permalink to &quot;Flows at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flow</th><th>Receipt path</th><th>Delivery path</th></tr></thead><tbody><tr><td>One step</td><td>Vendor → Stock</td><td>Stock → Customer</td></tr><tr><td>Two steps</td><td>Vendor → Input → Stock</td><td>Stock → Output → Customer</td></tr><tr><td>Three steps</td><td>Vendor → Input → Quality Control → Stock</td><td>Stock → Packing Zone → Output → Customer</td></tr></tbody></table><p>In the example warehouse the locations and operation types are:</p><table tabindex="0"><thead><tr><th>Step</th><th>Operation type</th><th>Prefix</th><th>From → To</th></tr></thead><tbody><tr><td>Receive</td><td>Receipts</td><td>WH/IN</td><td>Partners/Vendors → WH/Input</td></tr><tr><td>Check</td><td>Quality Control</td><td>WH/QC</td><td>WH/Input → WH/Quality Control</td></tr><tr><td>Store</td><td>Storage</td><td>WH/STOR</td><td>WH/Quality Control → WH/Stock</td></tr><tr><td>Pick</td><td>Pick</td><td>WH/PICK</td><td>WH/Stock → WH/Packing Zone</td></tr><tr><td>Pack</td><td>Pack</td><td>WH/PACK</td><td>WH/Packing Zone → WH/Output</td></tr><tr><td>Ship</td><td>Delivery Orders</td><td>WH/OUT</td><td>WH/Output → Partners/Customers</td></tr></tbody></table>',18)),d(o,{src:"/images1/inventory/route_overview_table.png",alt:"Operation Types list showing Receipts, Quality Control, Storage, Pick, Pack and Delivery Orders"}),t[1]||(t[1]=e('<h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><ul><li><a href="./one-step-flow.html">One step flow</a>: the simplest setup.</li><li><a href="./two-step-flow.html">Two step flow</a>: an extra staging step.</li><li><a href="./three-step-flow.html">Three step flow</a>: quality control, or pick and pack.</li><li><a href="./routes-and-rules.html">Routes and rules</a>: the forms behind the flows.</li><li><a href="./putaway-rules.html">Putaway rules</a>: choose the shelf for arriving goods.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../warehouses/warehouses.html">Warehouses</a></li><li><a href="./../warehouses/operation-types.html">Operation types</a></li><li><a href="./../warehouses/locations.html">Locations</a></li></ul>',4))])}const f=s(i,[["render",h]]);export{w as __pageData,f as default};
